self.FRX=self.FRX||{};(FRX.gx=FRX.gx||{})["id"]={"etre-present":["Être: adalah / menjadi","\"être\" berarti 'adalah' atau 'menjadi': \"je suis\", \"tu es\", \"il est\", \"nous sommes\", \"vous êtes\", \"ils sont\". Dipakai untuk identitas, asal, profesi, dan deskripsi. Hafalkan: ini kata kerja yang paling sering dipakai dalam bahasa Prancis. Contoh: \"je suis\", \"nous sommes\", \"ils sont\""],"avoir-present":["Avoir: punya","\"avoir\" berarti 'punya' atau 'memiliki': \"j'ai\", \"tu as\", \"il a\", \"nous avons\", \"vous avez\", \"ils ont\". Nanti ia juga membentuk passé composé. Perhatikan elisi \"j'ai\" sebelum bunyi vokal. Contoh: \"j'ai\", \"elle a\", \"nous avons\""],"il-y-a":["Il y a: ada","\"il y a\" memperkenalkan sesuatu yang ada, tunggal atau jamak, dan tidak pernah berubah: \"il y a un livre\", \"il y a des livres\". Negatif: \"il n'y a pas de livre\". Pertanyaannya \"y a-t-il\" atau \"est-ce qu'il y a\". Contoh: \"il y a un café\", \"il n'y a pas de lait\""],"art-defini":["Artikel tentu","\"le\" (maskulin), \"la\" (feminin), \"l'\" (sebelum vokal), dan \"les\" (jamak) berarti 'si, yang'. Bahasa Prancis juga memakainya untuk hal umum: \"j'aime la musique\" berarti 'saya suka musik'. Contoh: \"le café\", \"la pomme\", \"les enfants\""],"art-indefini":["Artikel tak tentu","\"un\" (maskulin), \"une\" (feminin), dan \"des\" (jamak) berarti 'seorang, sebuah' atau 'beberapa'. Dipakai untuk hal baru: \"j'ai un frère et des cousins\". Perhatikan: \"des\" sering tidak diterjemahkan dalam bahasa Indonesia. Contoh: \"un frère\", \"une sœur\", \"des amis\""],"gender-nouns":["Maskulin atau feminin?","Setiap kata benda itu maskulin atau feminin. Akhiran membantu: \"-tion\", \"-té\", \"-ette\" umumnya feminin; \"-ment\", \"-age\", \"-eau\" umumnya maskulin. Selalu hafalkan kata benda bersama artikelnya: \"la ville\", \"le village\". Contoh: \"le village\", \"la ville\", \"la question\""],"plural-regular":["Jamak: tambahkan -s","Kebanyakan jamak menambah \"-s\", yang tidak dilafalkan: \"un ami\", \"des amis\". Kata yang sudah berakhir \"-s\", \"-x\", atau \"-z\" tidak berubah: \"un pays\", \"des pays\". Hanya artikel dan liaison yang menandai jamak. Contoh: \"deux sœurs\", \"trois amis\""],"plural-irregular":["Jamak tak beraturan","Kata benda berakhir \"-al\" menjadi \"-aux\": \"un journal\", \"des journaux\". Yang berakhir \"-eau\" dan \"-eu\" menambah \"-x\": \"un bateau\", \"des bateaux\", \"un jeu\", \"des jeux\". Hafalkan beberapa pengecualian seperti \"un festival, des festivals\". Contoh: \"des journaux\", \"des bateaux\", \"des cheveux\""],"elision-basic":["Elisi sebelum vokal","Kata pendek \"le\", \"la\", \"je\", \"ne\", \"de\", \"que\", \"se\" kehilangan vokalnya sebelum vokal atau h bisu dan diberi apostrof: \"l'école\", \"j'aime\", \"n'aime pas\", \"qu'elle\". \"les\" dan \"un\" tidak pernah dielisi. Contoh: \"l'école\", \"j'aime\", \"qu'elle\""],"contractions-au-du":["au, aux, du, des","\"à + le\" menjadi \"au\", \"à + les\" menjadi \"aux\", \"de + le\" menjadi \"du\", \"de + les\" menjadi \"des\". Dengan \"la\" dan \"l'\" tidak ada perubahan: \"à la gare\", \"de la gare\". Jangan menulis \"à le\" atau \"de le\". Contoh: \"au marché\", \"aux voisins\", \"du professeur\""],"partitif":["Partitif: sebagian dari","Untuk menyebut jumlah sesuatu yang tidak bisa dihitung, pakai \"du\" (maskulin), \"de la\" (feminin), \"de l'\" (vokal), atau \"des\" (jamak): \"je prends du café\". Dalam bahasa Indonesia sering tanpa kata khusus, tetapi dalam bahasa Prancis selalu ada. Contoh: \"du pain\", \"de la salade\", \"des légumes\""],"de-negation":["Negasi + de","Setelah \"ne… pas\", \"jamais\", \"plus\", artikel tak tentu atau partitif menjadi \"de\": \"j'ai un chat\" menjadi \"je n'ai pas de chat\". Pengecualian: setelah \"être\" artikel tetap: \"ce n'est pas un chat\". Contoh: \"pas de voiture\", \"jamais de viande\""],"adj-agreement":["Kesesuaian adjektiva","Adjektiva menyesuaikan diri dengan kata bendanya: tambah \"-e\" untuk feminin dan \"-s\" untuk jamak. \"grand\", \"grande\", \"grands\", \"grandes\". Yang berakhir -e tetap sama pada feminin: \"un garçon sympa\", \"une fille sympa\". Contoh: \"elle est grande\", \"ils sont petits\""],"adj-position":["Di mana letak adjektiva?","Kebanyakan adjektiva diletakkan setelah kata benda: \"une robe bleue\". Beberapa yang pendek dan umum diletakkan sebelumnya: keindahan, usia, kebaikan, ukuran (\"beau, jeune, bon, grand, petit\"): \"un petit chien\". \"beau\" punya bentuk \"bel\" dan \"belle\". Contoh: \"une belle maison\", \"une maison blanche\""],"possessifs":["Posesif: mon, ma, mes","Posesif menyesuaikan diri dengan benda yang dimiliki, bukan pemiliknya: \"mon père\", \"ma mère\", \"mes parents\". Sebelum vokal, kata benda feminin memakai \"mon\": \"mon amie\". Lainnya: \"notre/nos\", \"votre/vos\", \"leur/leurs\". Contoh: \"mon père\", \"ma mère\", \"leurs chats\""],"demonstratifs":["Ini, itu: ce, cette, ces","\"ce\" (maskulin), \"cet\" (maskulin sebelum vokal), \"cette\" (feminin), dan \"ces\" (jamak) berarti 'ini' atau 'itu'. Tambahkan \"-ci\" atau \"-là\" untuk membandingkan: \"ce livre-ci\", \"ce livre-là\". Contoh: \"ce livre\", \"cette veste\", \"ces enfants\""],"pres-er":["Présent: kata kerja -er","Buang \"-er\" lalu tambahkan \"-e, -es, -e, -ons, -ez, -ent\": \"parler\" menjadi \"je parle\", \"tu parles\", \"il parle\", \"nous parlons\", \"vous parlez\", \"ils parlent\". Sekitar 90 persen kata kerja Prancis mengikuti pola ini. Contoh: \"je parle\", \"nous parlons\", \"ils parlent\""],"pres-ir-re":["Présent: kata kerja -ir dan -re","Kata kerja \"-ir\" beraturan menambah \"-is, -is, -it, -issons, -issez, -issent\": \"finir\", \"je finis\", \"nous finissons\". Kata kerja \"-re\" menambah \"-s, -s, -, -ons, -ez, -ent\": \"vendre\", \"je vends\", \"il vend\". Contoh: \"je finis\", \"nous finissons\", \"je vends\""],"pres-irreguliers":["Kata kerja tak beraturan umum","Pelajari \"aller\" (\"je vais, nous allons\"), \"faire\" (\"je fais, vous faites\"), \"prendre\" (\"je prends, ils prennent\"), dan \"venir\" (\"je viens, ils viennent\"). Hati-hati dengan \"vous faites\" dan \"ils font\": keduanya keluar dari pola. Contoh: \"je vais\", \"nous faisons\", \"ils prennent\", \"vous venez\""],"tu-vous":["Tu atau vous?","Pakai \"tu\" untuk teman, keluarga, anak-anak, dan sebaya. Pakai \"vous\" untuk orang asing, orang yang lebih tua, di toko dan di tempat kerja, dan selalu saat bicara dengan beberapa orang. Jika ragu, mulailah dengan \"vous\". Contoh: \"tu viens\", \"vous venez\""],"on-nous":["On = kita/kami","Dalam bahasa Prancis sehari-hari \"on\" menggantikan \"nous\", tetapi kata kerjanya tetap orang ketiga tunggal: \"on va au cinéma\". \"On\" juga berarti 'orang pada umumnya': \"en France, on mange du pain\". Contoh: \"on va\", \"on mange\""],"neg-ne-pas":["Negasi: ne … pas","Letakkan \"ne\" sebelum kata kerja dan \"pas\" sesudahnya: \"je ne parle pas\". Sebelum vokal \"ne\" menjadi \"n'\": \"il n'aime pas\". Dalam percakapan \"ne\" sering dibuang, tetapi tulislah dalam bahasa Prancis yang benar. Contoh: \"je ne parle pas\", \"il n'aime pas\""],"q-est-ce-que":["Pertanyaan ya/tidak","Paling mudah: pertahankan urutan kata dan naikkan nada suara, atau tulis tanda tanya: \"tu viens ?\". Lebih formal: taruh \"est-ce que\" di depan: \"est-ce que tu viens ?\". Sebelum vokal menjadi \"est-ce qu'\": \"est-ce qu'elle vient ?\". Contoh: \"tu aimes le thé ?\", \"est-ce que vous avez\""],"q-mots-interrogatifs":["Kata tanya","\"où\" (di mana), \"quand\" (kapan), \"comment\" (bagaimana), \"combien\" (berapa), \"pourquoi\" (mengapa), \"qui\" (siapa). Letaknya di awal: \"où est la gare ?\". Jawab \"pourquoi\" dengan \"parce que\". Contoh: \"où\", \"quand\", \"combien\", \"pourquoi\""],"q-quel":["Quel: yang mana, apa","\"quel\" menyesuaikan diri dengan kata benda: \"quel\" (m. tunggal), \"quelle\" (f. tunggal), \"quels\" (m. jamak), \"quelles\" (f. jamak). Ia bisa mengikuti kata benda setelah \"être\": \"quel est ton nom ?\" Contoh: \"quelle heure\", \"quels films\""],"futur-proche":["Masa depan dekat: aller + infinitif","Konjugasikan \"aller\" di présent lalu tambahkan infinitif: \"je vais travailler\", \"nous allons manger\". Negatif: \"je ne vais pas partir\". Ini cara biasa membicarakan rencana dalam percakapan. Contoh: \"je vais manger\", \"elle va partir\""],"pres-pronominaux":["Kata kerja refleksif (pronominal)","Kata kerja ini punya pronomina yang cocok dengan subjek: \"je me\", \"tu te\", \"il se\", \"nous nous\", \"vous vous\", \"ils se\". Contoh: \"se lever\", \"se coucher\", \"s'habiller\". Negatif: \"je ne me lève pas\". Contoh: \"je me lève\", \"elle se couche\""],"imperatif-present":["Imperatif (kalimat perintah)","Pakai bentuk présent untuk \"tu\", \"nous\", \"vous\" tanpa pronomina: \"tu parles\" menjadi \"parle !\", \"nous parlons\" menjadi \"parlons !\", \"vous parlez\" menjadi \"parlez !\". Kata kerja \"-er\" membuang -s akhir pada bentuk \"tu\". Tak beraturan: \"sois, soyons, soyez\", \"aie, ayons, ayez\". Contoh: \"parle !\", \"parlons !\", \"parlez !\""],"modaux-pouvoir-vouloir":["vouloir, pouvoir, devoir","Tiga kata kerja ini diikuti infinitif: \"je veux manger\", \"tu peux venir\", \"nous devons partir\". Ketiganya tak beraturan: \"je veux, nous voulons\", \"je peux, nous pouvons\", \"je dois, nous devons\". Contoh: \"je veux partir\", \"tu peux\", \"nous devons\""],"prep-lieu":["Di mana letaknya?","Kata tempat yang umum: \"dans\" (di dalam), \"sur\" (di atas), \"sous\" (di bawah), \"devant\" (di depan), \"derrière\" (di belakang), \"entre\" (di antara), \"à côté de\" (di sebelah), \"près de\" (dekat). Setelah \"de\", ingat kontraksinya: \"à côté du parc\". Contoh: \"sur la table\", \"sous la table\", \"entre la poste et la banque\""],"prep-a-chez-de":["à, chez, de","\"à\" dipakai untuk kota dan tempat: \"je vais à Lyon\". \"chez\" dipakai untuk orang atau toko/rumahnya: \"chez le dentiste\", \"chez moi\". \"de\" menyatakan asal: \"je viens de Lyon\". Contoh: \"chez Marie\", \"à Lyon\", \"de la gare\""],"nombres":["Angka","Bentuk khusus: \"soixante-dix\" (70), \"quatre-vingts\" (80, dengan -s), \"quatre-vingt-dix\" (90). \"et\" muncul pada 21, 31, 41, 51, 61, dan 71, tetapi tidak pada 81 dan 91. Tanda hubung menyambung puluhan dan satuan. Contoh: \"vingt et un\", \"soixante-dix\", \"quatre-vingts\""],"heure-date":["Jam dan tanggal","Pakai \"il est\" + jam: \"il est trois heures et quart\". \"midi\" dan \"minuit\" memakai \"et demi\", jam lain \"et demie\". Tanggal: \"le 5 mai\"; hanya tanggal 1 yang berupa bilangan tingkat: \"le premier mai\". Waktu memakai \"à\": \"à neuf heures\". Contoh: \"huit heures et demie\", \"le cinq mai\""],"c-est-ce-sont":["C'est, ce sont","Pakai \"c'est\" + kata benda tunggal dan \"ce sont\" + kata benda jamak untuk memperkenalkan atau mengenali: \"c'est un livre\", \"ce sont des livres\". Dalam percakapan, \"c'est\" juga umum dengan jamak. Pertanyaan: \"qu'est-ce que c'est ?\" Contoh: \"c'est mon frère\", \"ce sont mes amis\""],"gouts-aimer":["Suka dan tidak suka","Setelah \"aimer\", \"adorer\", \"détester\", dan \"préférer\" pakai artikel tentu, bukan partitif: \"j'aime le café\", \"elle adore les chats\". Tambahkan \"beaucoup\": \"j'aime beaucoup la musique\". Contoh: \"j'aime le chocolat\", \"je déteste les épinards\""],"adv-intensite":["Seberapa banyak?","\"très\" diletakkan sebelum adjektiva dan adverbia: \"très bien\". \"beaucoup\" diletakkan setelah kata kerja: \"il travaille beaucoup\". Sebelum kata benda pakai \"beaucoup de\": \"beaucoup de fruits\". \"un peu\" dan \"trop\" bekerja seperti \"beaucoup\". Contoh: \"très grand\", \"il mange beaucoup\", \"un peu\""],"avoir-expressions":["Ungkapan dengan avoir","Bahasa Prancis memakai \"avoir\", bukan \"être\", untuk usia dan banyak perasaan tubuh: \"j'ai vingt ans\", \"j'ai faim\", \"j'ai soif\", \"j'ai chaud\", \"j'ai froid\", \"j'ai peur\", \"j'ai sommeil\". Tambahkan \"très\": \"j'ai très faim\". Contoh: \"j'ai faim\", \"elle a vingt ans\", \"il a froid\""],"clause-et-mais-parce-que":["Kata penghubung","\"et\" menambahkan, \"ou\" memberi pilihan, \"mais\" mempertentangkan, \"parce que\" memberi alasan. Sebelum vokal \"parce que\" menjadi \"parce qu'\": \"parce qu'il pleut\". \"donc\" menyatakan akibat. Contoh: \"et\", \"mais\", \"parce que\""],"pc-avoir":["Passé composé dengan avoir","Kebanyakan kata kerja membentuk lampau dengan \"avoir\" di présent + participe passé: \"j'ai mangé\", \"tu as fini\", \"il a vendu\". Participe: \"-er\" menjadi \"-é\", \"-ir\" menjadi \"-i\", \"-re\" menjadi \"-u\". Contoh: \"j'ai mangé\", \"nous avons fini\""],"pc-etre":["Passé composé dengan être","Sekitar lima belas kata kerja memakai \"être\": \"aller, venir, arriver, partir, entrer, sortir, monter, descendre, rester, tomber, naître, mourir, retourner, passer\" dan semua kata kerja pronominal. Alat bantu ingatan: daftar bernama \"DR MRS VANDERTRAMP\". Contoh: \"je suis allé\", \"elle est partie\""],"pc-accord-etre":["Kesesuaian participe dengan être","Dengan \"être\", participe menyesuaikan diri dengan subjek: \"-e\" untuk feminin dan \"-s\" untuk jamak. \"il est parti\", \"elle est partie\", \"ils sont partis\", \"elles sont parties\". Contoh: \"elle est partie\", \"ils sont venus\", \"elles sont allées\""],"pc-pronominaux":["Kata kerja pronominal di masa lampau","Kata kerja pronominal memakai \"être\", dengan pronomina di depannya: \"je me suis levé\", \"elle s'est couchée\", \"ils se sont promenés\". Participe biasanya menyesuaikan dengan subjek. Contoh: \"je me suis levé\", \"elle s'est couchée\""],"pc-negation":["Lampau negatif","Letakkan \"ne … pas\" mengapit kata kerja bantu, bukan participe: \"je n'ai pas mangé\", \"elle n'est pas venue\". Sama dengan \"jamais\", \"plus\", \"rien\": \"il n'a rien dit\". Contoh: \"je n'ai pas mangé\", \"il n'est jamais venu\""],"pc-participes-irreguliers":["Participe tak beraturan","Bentuk yang wajib diketahui: \"avoir\" menjadi \"eu\", \"être\" menjadi \"été\", \"faire\" menjadi \"fait\", \"prendre\" menjadi \"pris\", \"voir\" menjadi \"vu\", \"dire\" menjadi \"dit\", \"écrire\" menjadi \"écrit\", \"mettre\" menjadi \"mis\", \"pouvoir\" menjadi \"pu\", \"vouloir\" menjadi \"voulu\". Contoh: \"j'ai eu\", \"j'ai été\", \"il a fait\", \"elle a pris\""],"imparfait-formation":["Imparfait: bentuk","Ambil bentuk \"nous\" di présent, buang \"-ons\", tambahkan \"-ais, -ais, -ait, -ions, -iez, -aient\": \"nous parlons\" menjadi \"je parlais\". Hanya \"être\" yang tak beraturan: \"j'étais, nous étions\". Contoh: \"je jouais\", \"nous allions\", \"il était\""],"imparfait-usage":["Imparfait: kapan dipakai","Pakai \"imparfait\" untuk latar sebuah cerita: cuaca, perasaan, deskripsi, dan kebiasaan yang berulang. \"Il faisait beau\", \"j'étais fatigué\", \"chaque été, nous allions à la mer\". Contoh: \"il faisait beau\", \"je jouais\", \"nous habitions\""],"impf-vs-pc":["Imparfait atau passé composé?","\"Imparfait\": apa yang sedang berlangsung, latarnya. \"Passé composé\": apa yang terjadi, satu peristiwa yang menggerakkan cerita. \"Je lisais quand le téléphone a sonné\": membaca sedang berlangsung, bunyi telepon menyelanya. Contoh: \"je dormais\", \"le téléphone a sonné\""],"futur-simple":["Futur simple","Ambil infinitif (buang -e akhir pada kata kerja \"-re\") lalu tambahkan \"-ai, -as, -a, -ons, -ez, -ont\": \"parler\" menjadi \"je parlerai\", \"prendre\" menjadi \"je prendrai\". Contoh: \"je parlerai\", \"nous prendrons\", \"ils finiront\""],"futur-irreguliers":["Akar futur tak beraturan","Akhirannya tetap sama tetapi akarnya berubah: \"aller\" menjadi \"ir-\", \"être\" menjadi \"ser-\", \"avoir\" menjadi \"aur-\", \"faire\" menjadi \"fer-\", \"venir\" menjadi \"viendr-\", \"pouvoir\" menjadi \"pourr-\", \"voir\" menjadi \"verr-\", \"vouloir\" menjadi \"voudr-\". Contoh: \"j'irai\", \"il fera\", \"ils viendront\""],"conditionnel-politesse":["Kondisional sopan","\"conditionnel\" melunakkan permintaan: \"je voudrais\" (saya ingin), \"pourriez-vous\" (bisakah Anda), \"j'aimerais\" (saya sangat ingin). Pembentukan: akar futur + akhiran imparfait \"-ais, -ais, -ait, -ions, -iez, -aient\". Contoh: \"je voudrais\", \"pourriez-vous\", \"nous aimerions\""],"cod-pronoms":["Pronomina objek langsung","\"le\", \"la\", \"l'\", dan \"les\" menggantikan kata benda tanpa preposisi dan berada sebelum kata kerja: \"je vois Paul\" menjadi \"je le vois\". Negatif: \"je ne le vois pas\". Contoh: \"je le vois\", \"elle la prend\", \"tu les aimes\""],"coi-pronoms":["Pronomina objek tak langsung","Untuk orang setelah \"à\", pakai \"lui\" (dia) dan \"leur\" (mereka): \"je parle à Marie\" menjadi \"je lui parle\", \"je téléphone à mes parents\" menjadi \"je leur téléphone\". \"leur\" di sini tidak pernah memakai -s. Contoh: \"je lui parle\", \"elle leur écrit\""],"pronoms-me-te-nous-vous":["me, te, nous, vous","Keempat pronomina ini bisa dipakai untuk objek langsung maupun tak langsung: \"il me voit\", \"il me parle\". Sebelum vokal \"me\" dan \"te\" menjadi \"m'\" dan \"t'\": \"je t'aime\", \"il m'écoute\". Contoh: \"il me voit\", \"elle nous parle\""],"y-pronom":["Pronomina y","\"y\" menggantikan \"à\" + benda atau sebuah tempat: \"je vais à Rome\" menjadi \"j'y vais\". Letaknya sebelum kata kerja: \"nous y allons\", \"je n'y vais pas\". Juga \"j'y pense\". Contoh: \"j'y vais\", \"nous y allons\""],"en-pronom":["Pronomina en","\"en\" menggantikan \"du, de la, des\" + kata benda atau \"de\" + kata benda. Jumlahnya tetap disebut: \"j'ai deux frères\" menjadi \"j'en ai deux\". Negatif: \"je n'en veux pas\". Contoh: \"j'en veux\", \"nous en avons deux\""],"pronoms-toniques":["Pronomina tonik","Pakai \"moi, toi, lui, elle, nous, vous, eux, elles\" setelah preposisi (\"avec moi\", \"chez eux\"), untuk penekanan (\"moi, je\"), dan berdiri sendiri (\"Qui est là ? Moi !\"). Juga setelah \"c'est\": \"c'est lui\". Contoh: \"avec moi\", \"chez lui\", \"eux\""],"comparatifs":["Membandingkan: plus … que","Pakai \"plus … que\" (lebih), \"moins … que\" (kurang), dan \"aussi … que\" (sama … dengan) di sekitar adjektiva atau adverbia: \"elle est plus rapide que lui\". Untuk kata benda: \"plus de … que\". Contoh: \"plus grand que\", \"moins cher que\", \"aussi rapide que\""],"superlatifs":["Superlatif","Letakkan artikel tentu sebelum \"plus\" atau \"moins\": \"le plus grand\", \"la plus belle\", \"les moins chers\". Untuk 'di antara' pakai \"de\": \"le plus grand de la classe\". Contoh: \"le plus grand\", \"la plus belle\", \"les moins chers\""],"meilleur-mieux":["meilleur atau mieux?","\"bon\" menjadi \"meilleur\" (adjektiva, menyesuaikan): \"une meilleure idée\". \"bien\" menjadi \"mieux\" (adverbia, tidak berubah): \"elle chante mieux\". Jangan pernah mengatakan \"plus bon\" atau \"plus bien\". Contoh: \"meilleur\", \"mieux\", \"la meilleure idée\""],"adverbes-ment":["Adverbia berakhiran -ment","Tambahkan \"-ment\" pada adjektiva feminin: \"lent\" menjadi \"lentement\", \"heureux\" menjadi \"heureusement\". Setelah vokal, tambahkan pada bentuk maskulin: \"vrai\" menjadi \"vraiment\". \"-ent\" menjadi \"-emment\": \"prudent\" menjadi \"prudemment\". Contoh: \"lentement\", \"vraiment\", \"prudemment\""],"prep-pays-villes":["Negara dan kota","Kota: \"à Paris\", \"de Paris\". Negara feminin: \"en France\", \"de France\". Negara maskulin: \"au Japon\", \"du Japon\". Negara jamak: \"aux États-Unis\", \"des États-Unis\". Contoh: \"en France\", \"au Japon\", \"aux États-Unis\", \"à Paris\""],"depuis-pendant-il-y-a":["depuis, pendant, il y a","\"depuis\" + présent: sesuatu yang masih berlangsung (\"j'habite ici depuis deux ans\"). \"pendant\" + durasi: berapa lama berlangsung (\"j'ai dormi pendant huit heures\"). \"il y a\" + durasi: sudah berapa lama (\"il est parti il y a une heure\"). Contoh: \"depuis deux ans\", \"pendant trois heures\", \"il y a une heure\""],"passe-recent":["Lampau dekat: venir de","Konjugasikan \"venir\" di présent lalu tambahkan \"de\" + infinitif: \"je viens de finir\", \"nous venons de partir\". Sebelum vokal \"de\" menjadi \"d'\": \"il vient d'arriver\". Contoh: \"je viens de manger\", \"ils viennent de partir\""],"imperatif-negatif":["Imperatif negatif","Apit kata kerja imperatif dengan \"ne … pas\": \"ne pars pas !\", \"ne partons pas !\", \"ne partez pas !\". Pronomina tetap sebelum kata kerja: \"ne le fais pas !\". Contoh: \"ne parle pas\", \"ne partez pas\""],"imperatif-pronoms":["Imperatif dengan pronomina","Pada imperatif afirmatif, pronomina mengikuti kata kerja dengan tanda hubung: \"regarde-moi\", \"parlez-nous\", \"dis-lui\". \"me\" menjadi \"moi\". Bentuk negatif memakai urutan biasa: \"ne me regarde pas\". Contoh: \"regarde-moi\", \"dis-lui\", \"donne-le-moi\""],"rel-qui-que":["qui dan que","\"qui\" menggantikan subjek: \"la femme qui habite ici\". \"que\" menggantikan objek langsung: \"le film que nous regardons\". \"que\" menjadi \"qu'\" sebelum vokal: \"le livre qu'il lit\". Contoh: \"l'homme qui parle\", \"le livre que je lis\""],"rel-ou":["où: di mana, ketika","\"où\" menghubungkan tempat atau waktu dengan klausa: \"la maison où elle habite\", \"le jour où nous sommes partis\". Dipakai untuk tempat maupun waktu. Contoh: \"la ville où j'habite\", \"le jour où\""],"il-faut":["il faut","\"il faut\" + infinitif berarti 'harus': \"il faut partir\". \"il faut\" + kata benda berarti 'butuh': \"il faut du temps\". \"il ne faut pas\" berarti 'tidak boleh'. Ini kata kerja impersonal: hanya \"il\". Contoh: \"il faut travailler\", \"il faut du temps\""],"neg-jamais-plus-rien":["jamais, plus, rien, personne","Semuanya menggantikan \"pas\": \"ne … jamais\" (tidak pernah), \"ne … plus\" (tidak lagi), \"ne … rien\" (tidak ada apa-apa), \"ne … personne\" (tidak ada siapa pun). \"rien\" dan \"personne\" juga bisa menjadi subjek: \"personne ne vient\". Contoh: \"je ne mange jamais\", \"il ne travaille plus\", \"nous ne voyons personne\""],"quantite-de":["Jumlah + de","Setelah kata jumlah pakai \"de\", tanpa artikel: \"beaucoup de travail\", \"un peu de sucre\", \"assez de temps\", \"trop de monde\", \"peu de gens\", \"une bouteille d'eau\". Contoh: \"beaucoup de travail\", \"un peu de sucre\", \"trop de monde\""],"c-est-il-est":["c'est atau il est?","Pakai \"il est\" / \"elle est\" + adjektiva atau profesi saja: \"il est médecin\", \"elle est gentille\". Pakai \"c'est\" bila ada artikel atau posesif: \"c'est un médecin\", \"c'est mon frère\". Contoh: \"c'est un médecin\", \"il est médecin\", \"elle est gentille\""],"q-inversion":["Inversi","Dalam bahasa Prancis yang cermat, kata kerja pindah ke depan pronomina subjek, disambung tanda hubung: \"parlez-vous ?\", \"où vas-tu ?\", \"que font-ils ?\". Jika kata kerja berakhir vokal, tambahkan \"-t-\": \"aime-t-il ?\". Contoh: \"parlez-vous\", \"où vas-tu\", \"que font-ils\""],"q-qui-que-quoi":["Siapa dan apa","\"qui\" menanyakan orang; \"que\" dan \"qu'est-ce que\" menanyakan benda: \"qu'est-ce que tu fais ?\". Setelah preposisi pakai \"qui\" (orang) atau \"quoi\" (benda): \"avec qui ?\", \"de quoi parles-tu ?\". Contoh: \"qui est-ce ?\", \"qu'est-ce que tu fais ?\", \"de quoi parles-tu ?\""],"adj-irreguliers":["beau, nouveau, vieux","Ketiganya punya bentuk khusus sebelum vokal maskulin: \"beau\" menjadi \"bel\", \"nouveau\" menjadi \"nouvel\", \"vieux\" menjadi \"vieil\". Feminin: \"belle\", \"nouvelle\", \"vieille\". Jamak: \"beaux\", \"nouveaux\", \"vieux\". Contoh: \"un bel homme\", \"une nouvelle voiture\", \"un vieil ami\""],"connecteurs-temps":["Pertama, lalu, akhirnya","\"d'abord\" (pertama), \"ensuite\" atau \"puis\" (lalu), \"après\" (sesudah itu), \"enfin\" (akhirnya) mengurutkan tindakan: \"d'abord je mange, puis je pars, enfin j'arrive\". Contoh: \"d'abord\", \"ensuite\", \"puis\", \"enfin\""],"si-present-futur":["si + présent, futur","Untuk kemungkinan nyata: \"si\" + présent pada syarat, futur (atau imperatif) pada hasilnya. \"si tu viens, je serai content\", \"si vous avez le temps, appelez-moi\". Jangan pernah memakai futur setelah \"si\". Sebelum \"il\" menjadi \"s'il\". Contoh: \"si tu viens, nous mangerons\", \"s'il pleut, je resterai\""],"savoir-connaitre":["savoir atau connaître?","\"savoir\" untuk fakta dan kemampuan: \"je sais nager\", \"je sais où il habite\". \"connaître\" untuk mengenal orang, tempat, dan benda: \"je connais Marie\", \"je connais cette ville\". Contoh: \"je sais nager\", \"je connais Paris\""],"pres-irreguliers-2":["Kata kerja tak beraturan lainnya","Pelajari dalam kelompok: \"lire\" (\"nous lisons\"), \"dire\" (\"vous dites\"), \"écrire\" (\"ils écrivent\"), \"voir\" (\"nous voyons\"), \"boire\" (\"ils boivent\"). Bentuk \"nous\" membantu membentuk imparfait. Contoh: \"nous lisons\", \"vous dites\", \"ils écrivent\""],"meteo-il":["Cuaca","Pakai \"il fait\" + adjektiva (\"il fait beau, froid, chaud\") dan kata kerja untuk hujan dan salju (\"il pleut\", \"il neige\"). Subjek \"il\" kosong dan tidak pernah berubah. Pertanyaan: \"quel temps fait-il ?\" Contoh: \"il fait beau\", \"il pleut\", \"il neige\""],"profession-sans-article":["Tanpa artikel untuk pekerjaan","Setelah \"être\", profesi, kebangsaan, atau agama tidak memakai artikel: \"il est médecin\", \"elle est française\". Dengan adjektiva, pakai \"c'est un\": \"c'est un bon médecin\". Contoh: \"elle est infirmière\", \"il est professeur\""],"subj-il-faut-que":["Subjonctif: il faut que","Setelah \"il faut que\" pakai subjonctif. Kata kerja beraturan: ambil akar présent \"ils\" lalu tambahkan \"-e, -es, -e, -ions, -iez, -ent\": \"ils partent\" menjadi \"que je parte\". Bentuk \"nous\" dan \"vous\" mirip imparfait. Contoh: \"il faut que tu viennes\", \"il faut que je parte\""],"subj-vouloir-que":["vouloir que + subjonctif","Bila subjek berganti, \"vouloir que\", \"préférer que\", \"aimer mieux que\", dan \"demander que\" memakai subjonctif: \"je veux que tu viennes\". Bila subjeknya sama, pakai infinitif: \"je veux venir\". Contoh: \"je veux que tu viennes\", \"elle veut que nous partions\""],"subj-irreguliers":["Subjonctif tak beraturan","Hafalkan: \"être\" (\"que je sois\"), \"avoir\" (\"que j'aie, qu'il ait\"), \"aller\" (\"que j'aille\"), \"faire\" (\"que je fasse\"), \"pouvoir\" (\"que je puisse\"), \"savoir\" (\"que je sache\"), \"vouloir\" (\"que je veuille\"). Contoh: \"que je sois\", \"qu'il ait\", \"que nous allions\", \"qu'ils fassent\""],"subj-emotions":["Perasaan + subjonctif","Setelah ungkapan perasaan (\"être content que\", \"être triste que\", \"regretter que\", \"avoir peur que\", \"être surpris que\") pakai subjonctif bila subjek berganti. Contoh: \"je suis content que tu sois là\", \"elle regrette que nous partions\""],"subj-vs-indic":["Indicatif atau subjonctif","Kepastian memakai indicatif: \"je pense que\", \"je sais que\", \"il est sûr que\". Keraguan, penyangkalan, dan kehendak memakai subjonctif: \"je ne pense pas que\", \"je doute que\", \"il faut que\". \"Penser que\" dalam pertanyaan boleh keduanya. Contoh: \"je pense qu'il a raison\", \"je ne pense pas qu'il ait raison\""],"subj-conjonctions":["Konjungsi + subjonctif","Beberapa konjungsi selalu memakai subjonctif: \"pour que\" (agar), \"avant que\" (sebelum), \"bien que\" (meskipun), \"à condition que\" (asalkan), \"jusqu'à ce que\" (sampai). \"après que\" memakai indicatif. Contoh: \"pour que tu comprennes\", \"avant que tu partes\", \"bien qu'il soit fatigué\""],"si-imparfait-cond":["si + imparfait, conditionnel","Untuk situasi khayalan atau kecil kemungkinan: \"si\" + imparfait, lalu conditionnel pada hasilnya. \"si j'étais riche, je voyagerais\". Jangan pakai conditionnel setelah \"si\". Contoh: \"si j'avais de l'argent\", \"j'achèterais une maison\""],"cond-usage":["Kondisional: saran dan keinginan","\"conditionnel\" memberi saran (\"tu devrais\"), menyatakan keinginan (\"j'aimerais\"), dan membuat usulan sopan (\"on pourrait\"). Dengan \"devoir\", \"pouvoir\", dan \"vouloir\" sangat umum. Contoh: \"tu devrais dormir\", \"nous aimerions voyager\""],"cond-passe-regret":["Penyesalan tentang masa lalu","Untuk hal yang tidak terjadi: \"si\" + plus-que-parfait, conditionnel passé. \"si tu avais étudié, tu aurais réussi\". Conditionnel passé adalah \"avoir\" atau \"être\" di conditionnel + participe passé. Contoh: \"si j'avais su\", \"je serais venu\""],"plus-que-parfait-forme":["Plus-que-parfait: bentuk","Kata kerja bantu di \"imparfait\" + participe passé: \"j'avais mangé\", \"elle était partie\", \"nous nous étions levés\". Aturan yang sama seperti passé composé menentukan \"avoir\" atau \"être\" dan kesesuaiannya. Contoh: \"j'avais fini\", \"nous étions partis\", \"elle avait mangé\""],"plus-que-parfait-usage":["Plus-que-parfait: penggunaan","Pakai \"plus-que-parfait\" untuk tindakan yang terjadi sebelum tindakan lampau lain atau sebelum suatu saat di masa lalu: \"quand je suis arrivé, il était déjà parti\". Sering menjelaskan sebab: \"il était fatigué, il n'avait pas dormi\". Contoh: \"le film avait déjà commencé\", \"il n'avait pas dormi\""],"di-present":["Kalimat tak langsung (présent)","Dengan \"dire que\", \"répondre que\", \"expliquer que\" di présent, kala klausa yang dilaporkan tidak berubah; hanya pronomina dan kata seperti \"mon\" yang berubah: \"« j'ai faim »\" menjadi \"il dit qu'il a faim\". Contoh: \"il dit qu'il est fatigué\", \"elle répond qu'elle ne sait pas\""],"di-questions":["Pertanyaan tak langsung","Pertanyaan ya/tidak memakai \"si\": \"il demande si tu viens\". Kata tanya tetap: \"où, quand, comment, pourquoi\". \"Qu'est-ce que\" menjadi \"ce que\", \"qu'est-ce qui\" menjadi \"ce qui\". Urutan kata seperti kalimat pernyataan. Contoh: \"il demande si je viens\", \"elle demande où j'habite\""],"di-passe":["Kalimat tak langsung (lampau)","Setelah \"a dit que\" kala bergeser mundur: présent menjadi \"imparfait\", futur menjadi \"conditionnel\", passé composé menjadi \"plus-que-parfait\". Kata waktu juga berubah: \"demain\" menjadi \"le lendemain\". Contoh: \"il a dit qu'il était fatigué\", \"elle a répondu qu'elle viendrait\""],"gerondif-formation":["Gérondif: bentuk","Ambil bentuk \"nous\" di présent, buang \"-ons\", tambahkan \"-ant\", dan taruh \"en\" di depan: \"nous travaillons\" menjadi \"en travaillant\". Pengecualian: \"être\" menjadi \"en étant\", \"avoir\" menjadi \"en ayant\", \"savoir\" menjadi \"en sachant\". Contoh: \"en travaillant\", \"en lisant\", \"en finissant\""],"gerondif-usage":["Gérondif: penggunaan","\"gérondif\" menyatakan dua tindakan terjadi bersamaan (\"il chante en travaillant\"), cara melakukan sesuatu (\"on apprend en lisant\"), atau syarat (\"en tournant à gauche, vous verrez la poste\"). Kedua kata kerja punya subjek yang sama. Contoh: \"on apprend en lisant\", \"il s'est blessé en jouant\""],"rel-dont":["dont: dari mana, yang ... -nya","\"dont\" menggantikan \"de\" + kata benda: \"je parle de ce livre\" menjadi \"le livre dont je parle\". Juga berarti 'yang ... -nya': \"la fille dont le père est médecin\". Juga setelah \"avoir besoin de\": \"ce dont j'ai besoin\". Contoh: \"le livre dont je parle\", \"la fille dont le père est médecin\""],"rel-ce-qui-ce-que":["ce qui, ce que, ce dont","Bila tidak ada kata benda di depan, pakai \"ce qui\" (subjek), \"ce que\" (objek), dan \"ce dont\" (dengan \"de\"): \"ce qui se passe\", \"ce que tu veux\", \"ce dont j'ai besoin\". Contoh: \"ce que tu veux\", \"ce qui se passe\", \"ce dont j'ai besoin\""],"pronoms-ordre":["Dua pronomina bersama","Urutan sebelum kata kerja: \"me, te, nous, vous\" + \"le, la, les\" + \"lui, leur\" + \"y\" + \"en\". \"me le\", \"te la\", \"nous les\", tetapi \"le lui\", \"les leur\": \"je le lui donne\". Contoh: \"je le lui donne\", \"elle me les envoie\""],"y-en-ensemble":["il y en a","Bila \"y\" dan \"en\" muncul bersama, \"y\" didahulukan: \"il y en a\", \"il n'y en a plus\". \"en\" mempertahankan jumlah: \"il y en a trois\". Contoh: \"il y en a\", \"nous y en avons\""],"imperatif-ordre-pronoms":["Imperatif: urutan pronomina","Afirmatif: kata kerja + objek langsung (\"le, la, les\") + tak langsung (\"moi, lui, nous, leur\") + \"y\" / \"en\": \"donne-le-moi\", \"dis-le-lui\". \"moi\" menjadi \"m'\" sebelum \"en\": \"donne-m'en\". Negatif: urutan biasa, \"ne me le donne pas\". Contoh: \"donne-le-moi\", \"dis-le-lui\", \"donne-m'en\""],"pronoms-possessifs":["Pronomina posesif","Menggantikan posesif + kata benda dan menyesuaikan dengan kata benda itu: \"le mien, la mienne, les miens, les miennes\", \"le tien\", \"le sien\", \"le nôtre\", \"le vôtre\", \"le leur\". \"Où est ma clé ? — Voici la mienne.\" Contoh: \"le mien\", \"la tienne\", \"les nôtres\""],"pronoms-demonstratifs":["celui, celle, ceux, celles","Menggantikan 'yang itu' dan diikuti \"de\", \"qui\", \"que\", atau \"-ci / -là\": \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\", \"celles-là\". Contoh: \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\""],"pronoms-indefinis":["Pronomina tak tentu","\"quelqu'un\" (seseorang), \"quelque chose\" (sesuatu), \"personne\" (tak seorang pun), \"rien\" (tak ada apa-apa), \"chacun\" (masing-masing), \"plusieurs\" (beberapa). Sebelum adjektiva pakai \"de\": \"quelque chose de bon\". Contoh: \"quelqu'un\", \"quelque chose de sucré\", \"chacun\""],"adj-indefinis":["chaque, plusieurs, quelques","\"chaque\" + kata benda tunggal (setiap), \"plusieurs\" dan \"quelques\" + kata benda jamak (beberapa, sedikit). \"tout\" menyesuaikan: \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Contoh: \"chaque élève\", \"plusieurs voitures\", \"toute la journée\""],"pc-accord-cod":["Kesesuaian participe dengan avoir","Dengan \"avoir\", participe menyesuaikan dengan objek langsung hanya bila objek itu berada sebelum kata kerja: \"j'ai acheté des fleurs\", tetapi \"les fleurs que j'ai achetées\", \"je les ai vues\". Contoh: \"les fleurs que j'ai achetées\", \"je les ai vues\""],"passif-forme":["Kalimat pasif","\"être\" (pada kala yang diperlukan) + participe passé yang menyesuaikan dengan subjek + \"par\": \"la lettre est écrite par Paul\", \"les maisons ont été détruites par le feu\". Objek kalimat aktif menjadi subjek. Contoh: \"le roman est écrit par\", \"la porte est ouverte par\""],"se-passif":["Pasif dengan se","Kata kerja orang ketiga dengan \"se\" bermakna pasif, tanpa pelaku: \"le vin se vend ici\", \"ça ne se dit pas\", \"cela se voit\". Sangat umum dalam percakapan dan aturan. Contoh: \"ça se dit\", \"ce produit se vend partout\""],"etre-en-train-de":["être en train de","\"être en train de\" + infinitif menekankan bahwa suatu tindakan sedang berlangsung sekarang: \"je suis en train de lire\". Setara dengan 'sedang' bila ingin menegaskan: \"ne l'appelle pas, il est en train de dormir\". Contoh: \"je suis en train de manger\", \"ils sont en train de partir\""],"pc-avoir-transitif":["Kata kerja sama, dua kata bantu","Bila \"sortir, monter, descendre, passer, rentrer, retourner\" punya objek langsung, kata bantunya \"avoir\": \"j'ai sorti la voiture\", \"elle a monté les escaliers\". Tanpa objek, \"être\": \"elle est sortie\". Contoh: \"il a sorti la valise\", \"elle a monté les escaliers\""],"futur-anterieur":["Futur antérieur","\"avoir\" atau \"être\" di futur simple + participe passé: \"j'aurai fini\", \"elle sera partie\". Menyatakan tindakan yang selesai sebelum tindakan masa depan lain: \"quand j'aurai fini, je t'appellerai\". Contoh: \"quand j'aurai fini\", \"dès qu'elle sera arrivée\""],"quand-futur":["quand + futur","Berbeda dengan bahasa Indonesia, bahasa Prancis memakai futur setelah \"quand\", \"dès que\", \"lorsque\", dan \"aussitôt que\" bila tindakannya di masa depan: \"dès qu'il arrivera, nous partirons\". \"Si\" pengecualian: tidak pernah dengan futur. Contoh: \"quand je serai grand\", \"dès qu'il arrivera\""],"connecteurs-cause-consequence":["Sebab dan akibat","\"car\" dan \"parce que\" memberi alasan; \"comme\" dan \"puisque\" membuka kalimat dengan alasan yang sudah diketahui: \"comme il pleut, je reste\". \"donc\" dan \"alors\" memberi hasil: \"il pleut, donc je reste\". Contoh: \"donc\", \"car\", \"comme\", \"puisque\""],"connecteurs-opposition":["Pertentangan","\"mais\", \"pourtant\", dan \"cependant\" mempertentangkan dua gagasan. \"alors que\" membandingkan dua fakta: \"elle aime le thé, alors que son mari préfère le café\". \"malgré\" + kata benda berarti 'meskipun': \"malgré la pluie\". Contoh: \"pourtant\", \"alors que\", \"malgré la pluie\""],"but-pour-afin-de":["Tujuan","Dengan subjek sama: \"pour\" atau \"afin de\" + infinitif: \"je travaille pour gagner de l'argent\". Dengan subjek berbeda: \"pour que\" atau \"afin que\" + subjonctif: \"il parle lentement pour que nous comprenions\". Contoh: \"pour gagner de l'argent\", \"afin de rentrer\", \"pour que nous comprenions\""],"neg-ne-que-ni":["ne … que, ni … ni, aucun","\"ne … que\" berarti 'hanya': \"je n'ai que dix euros\". \"ne … ni … ni\" berarti 'tidak ... maupun': \"elle ne mange ni viande ni poisson\". \"ne … aucun\" berarti 'tidak ada satu pun': \"il n'a aucun ami\". Contoh: \"je n'ai que dix euros\", \"ni viande ni poisson\", \"aucun ami\""],"neg-infinitif":["Infinitif negatif","Kedua bagian negasi berdampingan sebelum infinitif: \"ne pas partir\", \"ne plus fumer\", \"ne jamais mentir\". \"Il m'a demandé de ne pas fumer\". Contoh: \"ne pas fumer\", \"ne plus travailler\", \"ne jamais mentir\""],"q-lequel":["Lequel: yang mana","\"lequel\" menggantikan \"quel\" + kata benda dan menyesuaikan: \"lequel\" (m. tunggal), \"laquelle\" (f. tunggal), \"lesquels\" (m. jamak), \"lesquelles\" (f. jamak). \"Quel sac ? Lequel ?\" Setelah \"à\" dan \"de\": \"auquel\", \"duquel\". Contoh: \"lequel\", \"laquelle\", \"lesquels\""],"exclamations":["Seruan","\"quel\" + kata benda: \"quelle belle journée !\". \"comme\" atau \"que\" + klausa: \"comme il fait chaud !\", \"que c'est joli !\". Perhatikan spasi sebelum \"!\" dalam bahasa Prancis. Contoh: \"quelle belle journée !\", \"comme il fait chaud !\", \"que c'est joli !\""],"adv-place-pc":["Adverbia pendek di passé composé","Adverbia pendek yang umum (\"déjà, bien, mal, souvent, toujours, encore, trop, beaucoup\") berada di antara kata bantu dan participe: \"j'ai déjà mangé\", \"il a bien compris\". Adverbia tempat dan yang panjang diletakkan sesudahnya. Contoh: \"elle a déjà fini\", \"il a bien compris\""],"comparatifs-avances":["Makin lama makin, semakin … semakin","\"de plus en plus\" (makin lama makin banyak), \"de moins en moins\" (makin lama makin sedikit), \"plus … plus\" (semakin … semakin), \"autant de … que\" (sebanyak … seperti): \"elle a autant de livres que moi\". Contoh: \"de plus en plus froid\", \"plus on travaille, plus on apprend\", \"autant de livres\""],"prep-verbes":["Kata kerja dengan preposisi","Banyak kata kerja memerlukan preposisi tetap: \"penser à\", \"s'intéresser à\", \"répondre à\", \"parler de\", \"avoir besoin de\", \"avoir envie de\", \"rêver de\". Hafalkan bersama kata kerjanya. Contoh: \"penser à\", \"parler de\", \"avoir besoin de\", \"s'intéresser à\""],"prep-temps-en-dans":["en atau dans?","\"dans\" + durasi: kapan sesuatu akan terjadi, dihitung dari sekarang (\"le film commence dans une heure\"). \"en\" + durasi: berapa lama sesuatu dikerjakan (\"il a lu ce livre en deux jours\"). \"en\" juga dipakai dengan bulan dan tahun: \"en mai\", \"en 1998\". Contoh: \"dans une heure\", \"en deux jours\""],"inf-apres-prepositions":["Preposisi + infinitif","\"avant de\" + infinitif, \"après\" + infinitif lampau (\"avoir\" atau \"être\" + participe), \"sans\" + infinitif: \"avant de partir\", \"après avoir mangé\", \"sans dire au revoir\". Subjeknya harus sama. Contoh: \"avant de manger\", \"après avoir mangé\", \"sans dire\""],"faire-causatif":["faire + infinitif","\"faire\" + infinitif berarti menyuruh melakukan sesuatu (\"je fais réparer ma voiture\") atau membuat seseorang melakukan sesuatu (\"il fait rire les enfants\"). Infinitif langsung mengikuti \"faire\". Contoh: \"je fais réparer ma voiture\", \"il fait rire les enfants\""],"verbes-perception":["Melihat dan mendengar + infinitif","Setelah \"voir\", \"entendre\", \"regarder\", \"écouter\", \"sentir\" taruh infinitif: \"je les entends jouer\", \"nous voyons passer le train\". Pronomina adalah objek dari kata kerja persepsi. Contoh: \"je les entends chanter\", \"nous voyons passer le train\""],"voyelle-liaison-ecrite":["Bentuk khusus sebelum vokal","Sebelum vokal atau h bisu, beberapa kata berubah agar mudah dilafalkan: \"ma\" menjadi \"mon\" (\"mon amie\"), \"ce\" menjadi \"cet\" (\"cet homme\"), \"beau\" menjadi \"bel\" (\"un bel arbre\"), \"nouveau\" menjadi \"nouvel\", \"vieux\" menjadi \"vieil\". Contoh: \"mon amie\", \"cet homme\", \"un bel arbre\""],"tout-tous-toutes":["tout, tous, toute, toutes","Sebagai adjektiva, \"tout\" menyesuaikan: \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Sebagai pronomina berarti 'semuanya' (\"j'ai tout compris\") atau 'semua orang' (\"ils sont tous là\", dengan -s akhir dilafalkan). Contoh: \"tous les jours\", \"toute la journée\", \"ils sont tous là\""],"subj-after-bien-que":["Bien que + subjonctif","\"bien que\", \"quoique\", dan \"encore que\" menyatakan konsesi dan selalu memakai subjonctif, bahkan ketika faktanya pasti. Katakan \"Bien que le projet soit coûteux, nous continuons\", bukan \"bien que le projet est\". Contoh: \"Bien qu'il pleuve, nous sortons\", \"Quoiqu'elle soit jeune, elle dirige l'équipe\""],"subj-after-pour-que":["Tujuan: pour que, afin que","\"pour que\" dan \"afin que\" memperkenalkan tujuan dan diikuti subjonctif. Subjek klausa tujuan biasanya berbeda dari subjek utama: \"Je répète pour que vous compreniez\". Jika subjeknya sama, pakai \"pour\" atau \"afin de\" plus infinitif. Contoh: \"Il parle lentement pour que nous comprenions\", \"Elle écrit afin que tout soit clair\""],"subj-after-avant-que":["Batas waktu: avant que","\"avant que\" dan \"jusqu'à ce que\" memakai subjonctif karena tindakannya belum terjadi. Setelah \"avant que\" sering ditambahkan \"ne\" tanpa makna negatif: \"avant qu'il ne parte\". Pakai \"avant de\" plus infinitif jika subjeknya sama. Contoh: \"Attends jusqu'à ce que je revienne\", \"Appelle avant que nous ne partions\""],"subj-a-moins-que-ne":["Pengecualian: à moins que","\"à moins que\" berarti \"kecuali jika\" dan menuntut subjonctif. Bahasa Prancis formal sering menambahkan \"ne\" pelengkap sebelum kata kerja (\"à moins qu'il ne vienne\"), yang bukan negasi sebenarnya. Jangan pakai conditionnel atau futur setelahnya. Contoh: \"Je sors, à moins qu'il ne pleuve\", \"à moins que vous ne soyez occupé\""],"subj-a-condition-que":["Syarat: à condition que","\"à condition que\" dan \"pourvu que\" berarti \"asalkan\" dan memakai subjonctif, tidak pernah futur atau conditionnel. \"Pourvu que\" juga bisa membuka kalimat untuk menyatakan harapan: \"Pourvu qu'il vienne !\". Contoh: \"Je viendrai à condition que vous m'invitiez\", \"Pourvu que tout se passe bien\""],"subj-vs-ind-opinion":["Kata kerja opini: pilihan modus","Setelah \"penser que\" dan \"croire que\" dalam kalimat positif, pakai indicatif: \"Je pense qu'il a raison\". Dalam kalimat negatif atau pertanyaan dengan inversi, muncul keraguan sehingga dipakai subjonctif: \"Je ne pense pas qu'il ait raison\". Modus mengikuti seberapa yakin si pembicara. Contoh: \"Je crois qu'elle viendra\", \"Je ne crois pas qu'elle vienne\""],"subj-emotion-doubt":["Perasaan, keraguan, kebutuhan","Kata kerja emosi (\"être content que\", \"regretter que\"), keraguan (\"douter que\"), dan kebutuhan (\"il faut que\", \"il est essentiel que\") diikuti subjonctif ketika subjeknya berbeda. Klausa itu menyatakan reaksi atau kebutuhan, bukan fakta biasa. Contoh: \"Je suis ravi que vous veniez\", \"Il faut que nous partions\""],"subj-irregular-forms":["Bentuk subjonctif tak beraturan","Tujuh kata kerja umum punya bentuk dasar subjonctif tak beraturan: \"être\" (sois, soyons), \"avoir\" (aie, ayons), \"aller\" (aille, allions), \"faire\" (fasse), \"pouvoir\" (puisse), \"savoir\" (sache), \"vouloir\" (veuille). Hafalkan sebagai bentuk utuh; bentuk nous dan vous dari \"être\", \"avoir\", \"aller\", dan \"vouloir\" juga punya dasar sendiri. Contoh: \"qu'elle aille\", \"que vous sachiez\", \"que tu aies\""],"subj-passe":["Subjonctif lampau","Subjonctif lampau adalah subjonctif dari \"avoir\" atau \"être\" plus participe passé. Ia menunjukkan tindakan sudah selesai sebelum tindakan kata kerja utama: \"Je suis content que tu sois venu\". Pilih kata kerja bantu seperti di passé composé dan jaga kesesuaiannya. Contoh: \"Il faut qu'ils aient fini\", \"Bien qu'elle soit partie\""],"subj-vs-infinitive":["Subjonctif atau infinitif","Jika subjek kedua kata kerja sama, bahasa Prancis lebih suka infinitif: \"Je veux partir\". Jika subjek berganti, pakai \"que\" plus subjonctif: \"Je veux que tu partes\". Hal yang sama berlaku untuk keinginan, emosi, dan banyak konjungsi (\"avant de\" atau \"avant que\"). Contoh: \"Elle est contente d'être là\", \"Elle est contente que vous soyez là\""],"subj-superlative-relative":["Subjonctif setelah superlatif","Setelah superlatif (\"le plus\", \"le meilleur\") atau \"seul\", \"premier\", \"dernier\", \"unique\", klausa relatif memakai subjonctif, karena pernyataan itu berupa penilaian pribadi. Dengan \"jamais\", subjonctif lampau lazim dipakai: \"le plus beau film que j'aie vu\". Contoh: \"le seul homme qui sache\", \"la première fois que je le voie\""],"subj-relative-search":["Subjonctif untuk benda yang dicari","Ketika klausa relatif menggambarkan sesuatu yang kamu cari, inginkan, atau ragukan keberadaannya, pakai subjonctif: \"Je cherche un livre qui soit simple\". Jika kamu tahu benda itu ada, pakai indicatif: \"J'ai un livre qui est simple\". Pemicu khas: \"chercher\", \"vouloir\", \"il n'y a personne qui\", pertanyaan tentang keberadaan. Contoh: \"Y a-t-il quelqu'un qui puisse m'aider ?\""],"cond-passe-news":["Conditionnel untuk kabar belum pasti","Wartawan memakai conditionnel, sering conditionnel passé, untuk melaporkan informasi yang belum dikonfirmasi: \"Le ministre aurait démissionné\". Ia menandakan \"konon\" atau \"diduga\" dan penulis tidak menjamin faktanya. Pakai conditionnel présent untuk rumor saat ini: \"Il serait malade\". Contoh: \"Deux personnes seraient blessées\", \"selon certaines sources, le vol aurait été annulé\""],"si-plus-que-parfait":["Pengandaian lampau: si + plus-que-parfait","Untuk syarat yang tidak nyata di masa lalu, pakai \"si\" plus plus-que-parfait, dan conditionnel passé pada klausa hasil: \"Si j'avais su, je serais venu\". Jangan pernah menaruh conditionnel setelah \"si\" dengan makna ini. Klausa hasil menunjukkan apa yang tidak terjadi. Contoh: \"Si elle avait étudié, elle aurait réussi\", \"Si nous étions partis, nous aurions vu le concert\""],"si-mixed-conditions":["Kalimat pengandaian campuran","Pengandaian campuran menghubungkan syarat masa lalu dengan hasil masa kini: \"si\" plus plus-que-parfait, lalu conditionnel présent. Kata waktu seperti \"maintenant\" atau \"aujourd'hui\" pada hasil menunjukkan bahwa akibatnya masih berlaku sekarang. Contoh: \"Si tu avais écouté, tu comprendrais\". Bandingkan dengan pola yang sepenuhnya lampau: \"tu aurais compris\""],"hypothese-au-cas-ou":["Berjaga-jaga: au cas où","\"au cas où\" menyatakan tindakan berjaga-jaga terhadap kejadian yang mungkin terjadi dan diikuti conditionnel, bukan subjonctif atau futur. Artinya \"kalau-kalau\" atau \"untuk berjaga-jaga\". Ia bisa berada di awal atau di akhir kalimat. Contoh: \"Prenez un parapluie au cas où il pleuvrait\", \"Au cas où tu serais en retard, appelle-moi\""],"apres-que-indicatif":["après que + indicatif","\"après que\" dan \"dès que\" menyatakan fakta yang benar-benar terjadi, jadi memakai indicatif, bukan subjonctif (berbeda dari \"avant que\"). Kata kerja setelah \"après que\" memakai kala majemuk, lebih awal dari kata kerja utama: \"Après qu'il a fini, il est rentré\". Setelah \"dès que\" dengan kata kerja utama futur, pakai futur antérieur: \"Dès que tu auras fini, appelle-moi\""],"concordance-des-temps":["Konkordansi kala","Ketika kata kerja utama berbentuk lampau, kata kerja anak kalimat mundur satu langkah: présent menjadi imparfait, passé composé menjadi plus-que-parfait, futur menjadi conditionnel. Jangan mencampur kata kerja utama lampau dengan kata kerja anak kalimat présent: \"Il pensait que nous étions partis\". Contoh: \"Je savais que tu viendrais\", \"Elle disait qu'elle était fatiguée\""],"discours-indirect-passe":["Kalimat tidak langsung masa lalu","Dalam kalimat tidak langsung setelah kata kerja lampau (\"elle a dit que\"), geser kalanya: présent menjadi imparfait, passé composé menjadi plus-que-parfait, futur menjadi conditionnel. Kata waktu juga berubah: \"demain\" menjadi \"le lendemain\", \"hier\" menjadi \"la veille\", \"aujourd'hui\" menjadi \"ce jour-là\". Contoh: \"Il a dit qu'il viendrait le lendemain\""],"discours-indirect-questions":["Melaporkan pertanyaan","Dalam pertanyaan tidak langsung, pakai urutan kata biasa tanpa tanda tanya. \"Est-ce que\" dan pertanyaan ya/tidak menjadi \"si\": \"Il a demandé si je venais\". \"Qu'est-ce que\" menjadi \"ce que\", dan \"qu'est-ce qui\" menjadi \"ce qui\". Kala bergeser setelah kata kerja lampau. Contoh: \"Elle m'a demandé ce que je voulais\", \"Il voulait savoir ce qui se passait\""],"discours-indirect-ordres":["Melaporkan perintah dan permintaan","Untuk melaporkan perintah atau permintaan, pakai \"dire de\" atau \"demander de\" plus infinitif: \"Elle m'a dit de rentrer\". Orang yang dituju memakai \"à\" atau pronomina: \"Il a demandé à ses voisins de baisser la musique\". Perintah negatif menjaga \"ne pas\" tetap berdekatan sebelum infinitif: \"Il nous a dit de ne pas toucher aux câbles\""],"accord-participe-cod-avant":["Kesesuaian dengan objek di depan","Dengan \"avoir\", participe passé menyesuaikan dengan objek langsung hanya jika objek itu berada sebelum kata kerja. Cari \"que\", pronomina seperti \"les\", atau kata tanya: \"Les lettres que Marie a écrites\", \"Quelle robe as-tu choisie ?\". Jika objek berada sesudahnya, tidak ada kesesuaian: \"Marie a écrit des lettres\""],"accord-participe-pronominaux":["Participe kata kerja refleksif","Dalam passé composé kata kerja refleksif, participe menyesuaikan dengan pronomina refleksif jika ia berfungsi sebagai objek langsung: \"Les amies se sont retrouvées\". Participe tidak berubah jika pronominanya objek tak langsung atau ada objek lain sesudahnya: \"Elle s'est lavé les mains\", \"Ils se sont envoyé des messages\". Tanyakan pada dirimu apakah \"se\" berarti \"à qui ?\" atau \"qui ?\""],"participe-present-gerondif":["Participe, gérondif, adjektiva","Gérondif \"en + -ant\" menyatakan cara atau waktu suatu kejadian dan tidak berubah: \"Il s'est blessé en coupant du bois\". Participe présent menggantikan satu klausa dan juga tidak berubah: \"Les enfants jouant dans le jardin\". Adjectif verbal menyesuaikan dengan kata bendanya: \"une histoire fascinante\", \"des résultats surprenants\""],"passif-et-alternatives":["Pasif dan alternatifnya","Pasif memakai \"être\" + participe: \"Les résultats ont été annoncés par le jury\". Bahasa Prancis sering memilih alternatif: bentuk refleksif untuk fakta umum (\"Le fromage se mange après le plat\"), \"on\", atau \"se faire\" untuk sesuatu yang menimpa subjek (\"Il s'est fait voler son sac\")"],"causatif-faire-laisser":["Kausatif faire dan laisser","\"Faire\" + infinitif berarti menyebabkan sesuatu dikerjakan: \"Nous avons fait refaire la cuisine\". \"Laisser\" + infinitif berarti mengizinkan: \"Le professeur a laissé les élèves partir\". Participe \"fait\" tidak berubah sebelum infinitif: \"Ce film m'a fait pleurer\""],"pronoms-relatifs-composes":["Pronomina relatif majemuk","Setelah preposisi, pakai \"lequel\", \"laquelle\", \"lesquels\", atau \"lesquelles\" sesuai kata bendanya: \"la table sur laquelle\", \"les amis chez lesquels\". Dengan \"à\" bentuknya menyatu: \"auquel\", \"auxquels\", \"auxquelles\", \"à laquelle\". Dengan \"de\" menjadi \"duquel\", \"desquels\", \"de laquelle\""],"pronom-relatif-dont":["Pronomina relatif dont","\"Dont\" menggantikan \"de\" + kata benda dalam klausa relatif: \"L'ordinateur dont j'ai besoin\" (avoir besoin de). Ia juga menyatakan kepemilikan, dengan kata benda langsung sesudahnya: \"l'écrivain dont le dernier roman\". Dan ia memperkenalkan bagian dari suatu kelompok: \"trois enfants, dont deux vivent à l'étranger\""],"ce-qui-ce-que-ce-dont":["Ce qui, ce que, ce dont","\"Ce\" + pronomina relatif merujuk pada suatu gagasan atau hal yang tidak disebut namanya. \"Ce qui\" adalah subjek (\"Ce qui m'inquiète\"), \"ce que\" adalah objek (\"ce que tu veux\"). Pakai \"ce dont\" untuk kata kerja dengan \"de\" (\"ce dont tu as envie\") dan \"ce à quoi\" untuk kata kerja dengan \"à\" (\"ce à quoi il s'intéresse\")"],"pronoms-doubles-ordre":["Urutan dua pronomina","Sebelum kata kerja, letakkan pronomina tak langsung lebih dulu untuk me, te, nous, dan vous: \"Je te le rends\". Untuk orang ketiga, pronomina langsung lebih dulu: \"Je le lui donne\"; \"en\" selalu paling akhir: \"Je lui en ai parlé\". Setelah imperatif positif, urutannya langsung lalu tak langsung: \"Donne-les-moi\""],"pronoms-y-en-avances":["Y dan en tingkat lanjut","\"En\" menggantikan \"de\" + kata benda atau suatu jumlah, dan angkanya tetap: \"J'en ai acheté trois\". \"Y\" menggantikan \"à\" atau tempat: \"J'y pense tout le temps\". Dalam imperatif positif, keduanya mengikuti kata kerja dan digabung: \"Donnez-m'en un kilo\""],"mise-en-relief":["Penekanan dengan c'est...qui/que","\"C'est ... qui\" menyorot subjek dan \"c'est ... que\" menyorot objek atau pelengkap: \"C'est moi qui ai fait le gâteau\", \"C'est demain que nous partons\". Dengan kata benda jamak, pakai \"ce sont\": \"Ce sont mes voisins que j'ai invités\". Kata kerja setelah \"qui\" menyesuaikan dengan unsur yang ditekankan"],"inversion-peut-etre":["Inversi setelah adverbia kalimat","Dalam bahasa Prancis formal, \"peut-être\", \"sans doute\", dan \"aussi\" (bermakna \"karena itu\") di awal kalimat menuntut inversi subjek-kata kerja: \"Peut-être viendra-t-il demain\". Jika subjeknya kata benda, ulangi sebagai pronomina. Tambahkan \"-t-\" ketika kata kerja berakhir vokal sebelum \"il\" atau \"elle\": \"viendra-t-elle\""],"ne-expletif":["Ne pelengkap (ne explétif)","Setelah kata kerja rasa takut (\"craindre que\"), \"avant que\", dan komparatif ketidaksamaan, bahasa Prancis formal menambahkan \"ne\" tanpa makna negatif: \"Je crains qu'il ne pleuve\", \"avant qu'il ne fasse nuit\", \"plus grand que je ne pensais\". Dalam percakapan ia opsional dan tidak pernah dipakai bersama \"pas\""],"connecteurs-concession-opposition":["Konsesi dan pertentangan","\"Bien que\" + subjonctif dan \"malgré\" + kata benda menyatakan konsesi: \"Malgré la pluie, nous sommes sortis\". \"Alors que\" + indicatif mempertentangkan dua fakta: \"Paul adore la mer, alors que sa femme préfère la montagne\". \"Pourtant\", \"cependant\", dan \"en revanche\" menghubungkan dua kalimat"],"nominalisation":["Mengubah kata kerja jadi benda","Nominalisasi membuat tulisan lebih ringkas dan formal. Kata kerja menjadi kata benda dengan akhiran seperti -tion, -ment, -ure, atau -ée: \"ouvrir\" menjadi \"l'ouverture\", \"augmenter\" menjadi \"l'augmentation\", \"arriver\" menjadi \"l'arrivée\". Adjektiva juga bisa: \"difficile\" menjadi \"la difficulté\". Periksa genus kata benda baru"],"tout-accord":["Tout: adjektiva, pronomina, adverbia","Sebagai adjektiva, \"tout\" menyesuaikan dengan kata benda: \"tous les magasins\", \"toutes les fenêtres\". Sebagai adverbia bermakna \"sangat\", ia tidak berubah, kecuali sebelum adjektiva feminin yang diawali konsonan: \"elle est tout étonnée\" tetapi \"elles sont toutes timides\""],"prepositions-apres-verbes":["Preposisi setelah kata kerja","Beberapa kata kerja memakai preposisi tetap, dan preposisi itu bisa mengubah makna. \"Penser à\" berarti memikirkan: \"Je pense à mes vacances\"; \"penser de\" menanyakan pendapat: \"Que penses-tu de ce film ?\". Pelajari pasangan seperti \"s'habituer à\" dan \"se méfier de\" sebagai satu kesatuan"],"infinitif-passe":["Infinitif lampau","\"Après\" + \"avoir\" atau \"être\" + participe passé menyatakan tindakan yang terjadi sebelum tindakan utama: \"Après avoir écrit la lettre, il l'a postée\". Kedua tindakan harus berasal dari subjek yang sama. Kata kerja gerak dan kata kerja refleksif memakai \"être\" dan menyesuaikan: \"Après être rentrée\", \"Après nous être reposés\""],"a-regard-pronoms-lequel":["Lequel interogatif","\"Lequel\" menanyakan pilihan di antara hal yang sudah diketahui dan menyesuaikan dengannya: \"Lequel de ces chemins ?\", \"Laquelle de tes amies ?\". Dengan \"à\" atau \"de\" bentuknya menyatu: \"Auquel de ces clients as-tu téléphoné ?\", \"Duquel parles-tu ?\". Pakai \"quel\" hanya tepat sebelum kata benda"]};
